add(id=85, title="Units of analysis and pseudoreplication in laboratory biology", last_verified=V, prerequisites=["Modules 17, 21"],
 objectives=["Identify the independent experimental unit in fly, plant, microbial and cell experiments.", "Explain how pseudoreplication understates variance.", "Adjust or flag effect sizes when only non-independent n is available."],
 why="Treating non-independent observations as independent is among the most common reasons for false-positive findings - and it silently distorts meta-analyses because weights come from the (too small) variances.",
 plain="""The **experimental unit** is the smallest entity independently assigned to a treatment. Flies in one vial share food, microenvironment and handling: the **vial** is the unit, not the fly. Plants in one pot: the **pot**. Wells from one culture: the **culture**. **Technical replicates** (repeated measurements of one sample) are not independent either. **Pseudoreplication** (Hurlbert 1984) is analysing subunits as if they were units; Lazic (2010; 2018) shows how common it is in neuroscience and cell/animal experiments and asks 'what exactly is N?'.""",
 intermediate="""Consequences: SEs are too small, p-values too optimistic, and in a meta-analysis the study receives too much weight. **What to do:** (1) extract the unit-level n and summary (vial means ± SD across vials); (2) if only subunit data are given, approximate with the **design effect** DEFF = 1 + (m−1)ICC and effective n = n/DEFF (needs an ICC assumption: state and vary it); (3) otherwise flag the study (high risk of bias, 'independence of units') and run a sensitivity analysis excluding it. Do not 'fix' by guessing silently.""",
 advanced="""Mixed models with random effects for vial/cage handle subunits correctly; a meta-analyst receiving only subunit summaries cannot reproduce them. Estimating ICCs from studies that report both levels gives field-specific priors. Balanced equal cluster sizes are an assumption of the simple DEFF; unequal sizes require weighted formulas.""",
 assumptions=["Cluster sizes roughly equal for the DEFF formula.","ICC is assumed or taken from related data and tested in sensitivity analysis."],
 formulas=[dict(name="Design effect and effective sample size", tex=r"DEFF=1+(m-1)\,\rho,\qquad n_{eff}=\frac{n}{DEFF}", symbols={"m":"observations per cluster (e.g. flies per vial)","\\rho":"intra-class correlation","n":"total observations"})],
 worked_example="""A study reports n = 100 flies per group (5 vials × 20 flies). With ICC ρ = 0.10: DEFF = 1 + 19·0.10 = **2.9**; n_eff = 100/2.9 ≈ **34.5** per group - far more than the 5 true units, but far less than 100. The variance of a mean is therefore about **2.9 times** larger than the naive fly-level formula suggests. If the vial-level means are available, use n = 5 vials directly (the safest option).""",
 examples=[("Preclinical","Flies per vial; mice per cage."),("Plant","Plants per pot; subplots in split-plot designs."),("Microbiology","Technical replicates per culture."),("Education","Students per classroom."),("Cell biology","Wells per passage/experiment.")],
 mistakes=["Using fly n as n.","Counting technical replicates.","Ignoring clustering in meta-analysis weights.","Guessing the ICC silently."],
 misconceptions=[("'More flies always means more power.'","Only independent units add information."),("'Technical replicates are replicates.'","They measure assay noise, not biological variation.")],
 controversies=["Which ICC to assume.","Treating pseudoreplicated studies in sensitivity analyses."],
 decision_tree=[("Vial/cage/pot means reported?","Use them with n = units."),("Only subunit data?","DEFF-adjust with stated ICC + sensitivity; flag RoB."),("Unclear?","Contact authors; record as unclear.")],
 exercises=["For three studies in your area, identify the experimental unit.","Compute DEFF and n_eff for 8 vials × 25 flies at ICC 0.05, 0.1, 0.2.","Explain to a colleague why 3 vials of 100 flies is not n = 300."],
 integrity="Do not report pseudoreplicated n as if independent; state every adjustment and assumption.", further=["hurlbert1984","lazic2010","lazic2018","hedges2007cluster"],
 coding=dict(r='deff <- function(m, icc) 1 + (m - 1) * icc\nn <- 100; m <- 20\nc(deff(m, 0.10), n / deff(m, 0.10))   # 2.9, 34.5', python='from metalab import advanced as A\nd = A.design_effect(20, 0.10); print(d, 100 / d)   # 2.9 34.48'),
 application="**Milestone 7:** record the experimental unit and n at that level for every study; plan DEFF-based sensitivity analysis.", checklist=["Unit identified per study","Unit-level n extracted","Adjustments labelled","Sensitivity planned"],
 quiz=[dict(q="100 flies from 5 vials (20 flies each), ICC 0.10. DEFF?", opts=["2.9","1.9","20","0.1"], ans=0, why="1+(20−1)(0.10)=2.9.", numeric=True),
  dict(q="Effective n per group for those data?", opts=["34.5","100","5","2.9"], ans=0, why="100/2.9.", numeric=True),
  dict(q="Technical replicates are...", opts=["Not independent biological replicates","Independent units","Always better","Equal to vials"], ans=0, why="Assay noise."),
  dict(q="Safest data to extract when vial means are reported?", opts=["Vial-level means with n = number of vials","Fly-level SD with n = flies","The text's n","Median only"], ans=0, why="Correct unit."),
  dict(q="Pseudoreplication leads to...", opts=["Variances that are too small and false positives","Larger variances","No effect","Bias away from the null only"], ans=0, why="Hurlbert 1984; Lazic 2010.")])

add(id=86, title="Survival data and lifespan synthesis", last_verified=V, prerequisites=["Modules 27, 31, 85"],
 objectives=["Choose an appropriate effect measure for lifespan: median/mean ratios or hazard ratios.", "Extract or reconstruct survival information with labelled uncertainty.", "Pool log hazard ratios from published CIs."],
 why="Lifespan studies report survival in many incompatible ways. Choosing the wrong summary or treating reconstructed data as exact can mislead.",
 plain="""Common lifespan summaries: **mean lifespan**, **median lifespan**, **maximum lifespan** (a fragile extreme), **survival curves** (Kaplan-Meier) and **hazard ratios (HR)** from Cox or similar models. Choose *in the protocol*: for ratio-scale lifespans (days) a **log ratio of medians or means** (lnRR) is often practical; HRs use the whole curve but need log-HR and SE. Median lifespan ignores curve shape; maximum lifespan has poor statistical properties.""",
 intermediate="""**Log HR meta-analysis:** pool ln(HR) with SE = (ln U − ln L)/(2·1.96) from the reported CI (Parmar et al. 1998 describe how to extract such statistics when they are not reported directly; Tierney et al. 2007 give practical methods for incorporating summary time-to-event data). When only curves are published, individual data can be **reconstructed** from digitised Kaplan-Meier curves with numbers at risk (Guyot et al. 2012) - an *estimate* requiring assumptions; label values as reconstructed and test sensitivity. For fly/worm assays, check censoring (escapes, accidental deaths), vial structure (Module 85) and sex.""",
 advanced="""The proportional-hazards assumption may fail (e.g. interventions that change the late-life mortality rate); then a single HR is a weighted average. Restricted mean survival time is an alternative. With the exponential assumption, HR = median_ctrl/median_treat, but real lifespans are not exponential: do not convert medians to HRs except as a flagged approximation. Dependence arises when sexes or doses share controls.""",
 assumptions=["Proportional hazards (for HR).","Reconstruction assumes digitisation accuracy and independent censoring.","Vial/cohort is the unit."],
 worked_example="""A study reports HR = 0.75 (95% CI 0.60 to 0.94). ln(0.94) = −0.0619; ln(0.60) = −0.5108; SE = (−0.0619 − (−0.5108)) / (2·1.96) = **0.1145**; ln HR = ln(0.75) = **−0.2877**. For median lifespans of 40 vs 48 days a flagged *approximation* under the exponential assumption gives HR ≈ 40/48 = **0.83**, while lnRR of medians (treated/control) = ln(48/40) = **0.1823** (+20%).""",
 examples=[("Preclinical","Drosophila lifespan curves by sex."),("Clinical","Overall survival HRs."),("Ecology","Survival of transplants."),("Microbiology","Time-to-kill."),("Plant","Time to wilting.")],
 mistakes=["Using maximum lifespan as the primary outcome.","Treating reconstructed data as reported.","Ignoring censoring.","Converting medians to HRs silently."],
 misconceptions=[("'Mean and median lifespan are interchangeable.'","They differ with skewed or non-exponential survival."),("'One HR describes the whole curve.'","Only under proportional hazards.")],
 controversies=["Primary lifespan summary in model-organism meta-analysis.","Use of reconstructed individual data."],
 decision_tree=[("HR + CI reported?","Pool ln HR."),("Medians/means + variance?","lnRR or SMD per protocol."),("Only curves?","Digitise/reconstruct + label + sensitivity."),("Late-life effects?","Consider RMST/curve-shape analyses (specialist).")],
 exercises=["Convert HR 0.75 (0.60–0.94) to ln HR and SE.","State your protocol's primary lifespan metric and justify it.","List what you would need to reconstruct one curve."],
 integrity="Label reconstructed survival data and report sensitivity analyses; never present reconstruction as source data.", further=["parmar1998","tierney2007","guyot2012","hedges1999"],
 coding=dict(r='hr <- 0.75; lo <- 0.60; hi <- 0.94\nse <- (log(hi) - log(lo)) / (2 * qnorm(0.975)); c(log(hr), se)   # -0.2877 0.1145\nlog(48/40)                                                        # 0.1823', python='import math\nse = (math.log(0.94) - math.log(0.60)) / (2 * 1.959964)\nprint(math.log(0.75), se, math.log(48/40))'),
 application="**Milestone 7/9:** fix the primary lifespan metric in the protocol; plan extraction of HRs/medians; label reconstructed values.", checklist=["Primary metric pre-specified","Censoring handled","Reconstructed values labelled","Sensitivity planned"],
 quiz=[dict(q="SE of ln(HR) from CI 0.60–0.94?", opts=["0.1145","0.25","0.0619","1.96"], ans=0, why="(ln0.94−ln0.60)/(2×1.96).", numeric=True),
  dict(q="lnRR for median lifespans 40 vs 48 days (treated/control)?", opts=["0.182","0.833","8","-0.182"], ans=0, why="ln(48/40).", numeric=True),
  dict(q="Maximum lifespan as a primary outcome is...", opts=["Statistically fragile","Preferred","Standard","Required"], ans=0, why="Extreme value."),
  dict(q="Reconstructed survival data should be...", opts=["Labelled as reconstructed with sensitivity analysis","Treated as reported","Hidden","Averaged"], ans=0, why="Guyot 2012 is an estimation method."),
  dict(q="Proportional hazards means...", opts=["The HR is constant over time","The curves are parallel in days","Medians equal","No censoring"], ans=0, why="Definition.")])

add(id=87, title="Sex as a biological variable in evidence synthesis", last_verified=V, prerequisites=["Modules 36, 85"],
 objectives=["Extract and analyse sex-specific results correctly.", "Test sex differences formally rather than comparing p-values.", "Report limitations when sex is confounded or unreported."],
 why="Many studies use one sex or pool sexes; reviews that ignore sex miss heterogeneity and can mislead. Beery & Zucker (2011) documented sex bias in neuroscience and biomedical research; Garcia-Sifuentes & Maney (2021) examined reporting and misreporting of sex differences across the biological sciences (cited as further reading; their abstracts were not examined here).""",
 plain="""Plan sex in the protocol: extract results **by sex** where reported; record when studies used one sex, mixed sexes without breakdown, or did not state sex. The right comparison for 'does the effect differ by sex?' is the **difference between sex-specific effects** with its SE (an interaction test), not 'significant in males but not in females'. Within-study comparisons (both sexes in the same experiment) are far stronger evidence than between-study contrasts.""",
 intermediate="""For effects θ_M and θ_F with SEs s_M and s_F from the *same study*, the difference is θ_M − θ_F with SE ≈ √(s_M² + s_F²) when independent (sexes are usually separate animals, but a **shared control** breaks independence - Module 38). Across studies, meta-regression on sex (within-study contrast) or a multilevel model handles clustering. Report numbers of studies per sex category: missing or pooled sex is itself a finding.""",
 advanced="""Housing, genotype, diet and developmental stage can differ by sex, confounding a naive comparison. Sex-by-intervention heterogeneity is a pre-specified moderator candidate; with few studies it is exploratory. Report whether sex was randomised, whether females were synchronised for oestrous/mating status where relevant (in flies: mating status), and whether analysis was sex-stratified a priori.""",
 assumptions=["Sex-specific data are independent or dependence is modelled.","Sex is reported reliably."],
 worked_example="""Male lnRR = 0.10 (SE 0.04) → z = 2.50, p = 0.012 ('significant'). Female lnRR = 0.02 (SE 0.05) → z = 0.40, p = 0.69 ('not significant'). Difference = **0.08**, SE = √(0.04²+0.05²) = **0.064**, z = **1.25**, p = **0.21**: no good evidence the effect differs by sex, despite the contrasting p-values.""",
 examples=[("Preclinical","Lifespan interventions by sex."),("Clinical","Trial subgroup by sex."),("Ecology","Sex-biased dispersal outcomes."),("Genetics","X-linked effects."),("Neuroscience","Single-sex studies.")],
 mistakes=["Comparing p-values across sexes.","Ignoring studies with unreported sex.","Treating shared controls as independent.","Over-interpreting few studies."],
 misconceptions=[("'No significant effect in females means no effect.'","Check power and the difference test."),("'Males are the default.'","Report sex explicitly.")],
 controversies=["Sex as moderator vs separate analyses.","Handling unreported sex."],
 decision_tree=[("Both sexes in the same study?","Compute within-study difference."),("Only one sex per study?","Between-study contrast; exploratory."),("Sex unreported?","Own category; sensitivity.")],
 exercises=["Compute the sex difference and test for the example numbers.","Add 'sex' extraction fields to your form.","State how you will handle shared controls across sexes."],
 integrity="Pre-specify the sex analysis; report all sex-specific results including null ones.", further=["beery2011","garciasifuentes2021","oxman1992","thompson2002"],
 coding=dict(r='est <- c(0.10, 0.02); se <- c(0.04, 0.05)\ndiff <- est[1] - est[2]; se_d <- sqrt(sum(se^2))\nc(diff, se_d, diff/se_d, 2*pnorm(-abs(diff/se_d)))', python='import math\nfrom scipy import stats\nd = 0.10 - 0.02; sd = math.hypot(0.04, 0.05); z = d / sd\nprint(d, sd, z, 2 * stats.norm.sf(abs(z)))'),
 application="**Milestone 2/7:** add sex fields; decide the sex analysis in the protocol.", checklist=["Sex fields in the form","Interaction test planned","Dependence handled","Unreported sex category"],
 quiz=[dict(q="Male effect 0.10 (SE 0.04), female 0.02 (SE 0.05). z for the sex difference?", opts=["1.25","2.5","0.4","0.08"], ans=0, why="0.08/0.064.", numeric=True),
  dict(q="Significant in males, not in females shows...", opts=["Nothing about a sex difference without a difference test","A sex difference","No effect in females","Bias"], ans=0, why="Test the interaction."),
  dict(q="Strongest evidence of a sex difference?", opts=["Within-study comparison in one experiment","Between-study contrast","Single-sex study","Narrative claim"], ans=0, why="Confounding."),
  dict(q="Studies with unreported sex should be...", opts=["Recorded as a category and tested in sensitivity analysis","Ignored","Assumed male","Deleted"], ans=0, why="Transparency."),
  dict(q="Shared controls across sexes cause...", opts=["Dependent effect sizes","No issue","Bias only","Zero variance"], ans=0, why="Module 38.")])

add(id=38, title="Dependent effect sizes: shared controls, multiple outcomes and clusters", last_verified=V, prerequisites=["Modules 32, 85"],
 objectives=["Recognise sources of dependence among effect sizes.", "Apply simple remedies (split controls, aggregate) and when to use multilevel or robust methods.", "Understand what MetaLab does and does not implement."],
 why="Standard meta-analysis assumes independent effect sizes. Dependence understates variance and overstates certainty.",
 plain="""Dependence arises from: **shared controls** (several treatments vs one control), **multiple outcomes** or **time points** from the same units, **multiple effect sizes per study/lab/site**, and **phylogenetic or spatial** relatedness. Ignoring it counts the same information more than once.""",
 intermediate="""Remedies (simplest first): (1) choose one effect per study by a pre-specified rule; (2) **split the shared control** n across comparisons; (3) **aggregate** within study; (4) **multilevel (three-level) models** with study/cluster random effects (Cheung 2014; Assink & Wibbelink 2016); (5) **robust variance estimation** (Hedges, Tipton & Johnson 2010; small-sample corrections by Tipton and Pustejovsky). Multilevel models with a diagonal V assume sampling errors are independent within clusters - not true for shared controls, which need covariance matrices.""",
 advanced="""RVE gives valid inference for the mean effect without specifying the dependence structure but needs enough clusters and small-sample corrections (CR2/Satterthwaite) that MetaLab does not implement (CR1 only). Choosing assumed within-study correlations affects efficiency, not validity, under RVE; sensitivity analysis is standard.""",
 assumptions=["Dependence sources identified a priori.","Enough clusters for multilevel/RVE (>~10)."],
 worked_example="""Two treatments (n=60 each) share one control (n=60), SD=3. Treating them as independent uses variances 9/60+9/60 = **0.30** each; but the control contributes to both estimates. A simple remedy splits the control: each comparison uses n_c=30, variance 9/60+9/30 = **0.45** (more honest, less precise). In MetaLab, the Virtual Lab clinical/ecology/microbiology scenarios practise recording a shared control_group_id; the Statistics Lab's three-level model + CR1 handles cluster dependence on the published Konstantopoulos data.""",
 examples=[("Preclinical","Two sexes, one control cohort."),("Clinical","Multi-arm trials."),("Ecology","Many sites per study."),("Education","Several outcomes per classroom."),("Microbiology","Several temperatures vs one control.")],
 mistakes=["Treating shared-control comparisons as independent.","Averaging outcomes without a rule.","Using RVE with 4 clusters.","Not reporting the dependence handling."],
 misconceptions=[("'Random effects handles dependence.'","Only for between-study heterogeneity."),("'RVE fixes everything.'","Needs enough clusters.")],
 controversies=["Assumed correlations.","Small-sample corrections."],
 decision_tree=[("Shared control?","Split n or model covariance."),("Many effects per study?","Multilevel or RVE."),("Few clusters?","Select one effect/aggregate; be cautious.")],
 exercises=["Identify dependence in your planned dataset.","Compute the split-control variance for your numbers.","Run the three-level model in the Statistics Lab and read the variance components."],
 integrity="Report how dependence was handled; do not ignore known dependence.", further=["cheung2014","assink2016","hedges2010rve","tipton2015","pustejovsky2021","viechtbauer2010"],
 coding=dict(r='library(metafor)\n# three-level model: effects nested in studies\nres <- rma.mv(yi, vi, random = ~ 1 | district/school, data = dat.konstantopoulos2011)\nres\nrobust(res, cluster = district)', python='from metalab import advanced as A\nfrom metalab.datasets import KON_YI, KON_VI, KON_DISTRICT\nfit = A.multilevel_meta(KON_YI, KON_VI, KON_DISTRICT); print(fit["sigma2_cluster"], fit["sigma2_effect"], A.robust_cr1(fit)["se"])'),
 application="**Milestone 9/10:** list dependence sources; choose and pre-specify the handling.", checklist=["Dependence sources listed","Handling pre-specified","Limitations stated"],
 quiz=[dict(q="Shared-control comparisons are...", opts=["Statistically dependent","Independent","Unbiased","Irrelevant"], ans=0, why="Common control."),
  dict(q="Splitting a shared control n=60 between two comparisons gives each comparison n_c =", opts=["30","60","120","15"], ans=0, why="60/2.", numeric=True),
  dict(q="Random effects across studies alone...", opts=["Does not model within-study dependence","Handles all dependence","Is RVE","Removes bias"], ans=0, why="Different structure."),
  dict(q="RVE requires...", opts=["Enough clusters and small-sample corrections","No assumptions","Two studies","Normality only"], ans=0, why="Tipton 2015."),
  dict(q="MetaLab implements...", opts=["Three-level REML + CR1 only (not CR2, not shared-control covariance)","Full RVE with CR2","Network MA","Bayesian multilevel"], ans=0, why="Stated limits.")])

add(id=59, title="Preclinical and animal research evidence synthesis", last_verified=V, prerequisites=["Modules 22, 85"],
 objectives=["Plan an animal/model-organism review: species, strain, sex, age, housing, units.", "Use SYRCLE-style appraisal and ARRIVE-based extraction appropriately.", "Anticipate small-study effects and translational indirectness."],
 why="Preclinical evidence is heterogeneous and often biased by design; synthesis can expose this but only if methods are careful.",
 plain="""Extract and later analyse: **species/strain/genotype, sex, age, housing/diet, dose/duration, unit (cage/vial), randomisation and blinding reports**. Use SYRCLE's tool (Hooijmans 2014) for animal intervention studies - for invertebrates, document how items are interpreted. **ARRIVE** (Percie du Sert 2020) is a *reporting* guideline for primary studies, not a risk-of-bias tool. A practical guide to meta-analysis of animal data exists (Vesterinen et al. 2014).""",
 intermediate="""Heterogeneity is expected (strain, lab, diet): use random effects, prediction intervals and pre-specified moderators; beware pseudoreplication (Module 85) and shared controls (Module 38). Small-study effects and publication bias are documented problems in preclinical literatures (Module 50). Indirectness: model-organism results do not automatically translate; state the target question (e.g. 'in flies') rather than implying human relevance.""",
 advanced="""Multi-lab replication studies provide the best estimates of between-lab variance. Systematic searching should include species-specific nomenclature and database coverage (Module 9/10). Registration platforms for animal studies exist (candidate resources in the Knowledge Universe; verify them yourself).""",
 assumptions=["Units correctly identified.","Appraisal interpretation rules documented."],
 worked_example="""Fly lifespan review: extract genotype (e.g. w1118 vs Canton-S), sex, temperature, diet, n_vials, mean/median lifespan, SD; appraise with an adapted SYRCLE (rules: 'random housing' = randomised incubator positions; 'blinding' = who scored deaths). Pre-specify moderators: sex, genotype background, diet. Use lnRR for ratio-scale lifespan; flag studies lacking vial structure.""",
 examples=[("Fly","Lifespan, healthspan."),("Mouse","Behavioural outcomes."),("Zebrafish","Regeneration."),("Worm","Survival assays."),("Rat","Pharmacology.")],
 mistakes=["Using ARRIVE as risk of bias.","Ignoring strain/lab.","Pooling species uncritically.","Over-translating."],
 misconceptions=[("'Animal studies are homogeneous.'","Often highly heterogeneous."),("'Blinding is rarely relevant.'","Outcome assessment is vulnerable.")],
 controversies=["Applicability of SYRCLE to invertebrates.","Pooling across species."],
 decision_tree=[("One species/strain family?","Pool with moderators."),("Many species?","Subgroup/mapping."),("Translational claim?","Hedged; indirectness.")],
 exercises=["Adapt SYRCLE items for your organism and write rules.","List moderators for your review.","Draft the extraction fields for strain/sex/housing."],
 integrity="State adaptations of appraisal tools; avoid translational over-claims.", further=["hooijmans2014","arrive2020","vesterinen2014","nakagawa2012"],
 application="**Milestones 4/7/8:** preclinical form + adapted RoB rules in the protocol.", checklist=["Unit defined","RoB rules documented","Moderators pre-specified","Indirectness addressed"],
 quiz=[dict(q="ARRIVE is...", opts=["A reporting guideline for primary animal studies","A risk-of-bias tool","A database","A registry"], ans=0, why="Percie du Sert 2020."),
  dict(q="SYRCLE applies to...", opts=["Animal intervention studies (adapt for invertebrates)","Only humans","Qualitative studies","Economic studies"], ans=0, why="Hooijmans 2014."),
  dict(q="Which is a unit problem?", opts=["Flies analysed instead of vials","Using REML","Using HKSJ","Plotting a funnel"], ans=0, why="Module 85."),
  dict(q="Preclinical heterogeneity usually calls for...", opts=["Random effects + prediction intervals + moderators","Common effect","Ignoring strain","Vote counting"], ans=0, why="Expected variation."),
  dict(q="Translational claims should be...", opts=["Hedged given indirectness","Stated as certain","Omitted from Discussion","Made in the title"], ans=0, why="Model ≠ target.")])

add(id=61, title="Plant biology and agricultural syntheses", last_verified=V, prerequisites=["Modules 27, 85"],
 objectives=["Define units (plot, pot, block) in plant experiments.", "Use lnRR for biomass/yield; handle split-plot structures.", "Plan moderators: stress severity, soil, cultivar, system."],
 why="Plant studies are rich in nested designs and field variation; naive pooling mixes incompatible units.",
 plain="""Typical outcomes: biomass, yield, germination, photosynthesis. **Ratio-scale** outcomes suit **lnRR** (Hedges et al. 1999; widely used in ecology and plant science - see Koricheva & Gurevitch 2014 on uses and misuses of meta-analysis in plant ecology). Units: plot/pot/block, not plants. Greenhouse vs field and **split-plot** designs matter; record the design and which table gives unit-level data.""",
 intermediate="""Moderators: stress type/severity, soil, cultivar/genotype, growing season, system (greenhouse/field), duration. Geographic variation → random effects and meta-regression with caution. Multiple outcomes per study (several harvests) create dependence (Module 38). Germination/survival proportions: use logit/RR with plate/plot as the unit. Standardise units (t/ha vs g/plant) *before* lnRR - lnRR is unit-free only if both means share the unit.""",
 advanced="""Zero or negative means (e.g. net growth change) invalidate lnRR; alternatives: SMD or MD. Small-sample bias of lnRR matters when n is small and means are close to zero. Phylogenetic non-independence can matter for cross-species syntheses.""",
 assumptions=["Positive ratio-scale means.","Unit-level n."],
 worked_example="""Inoculated mean 4.8 kg/plot (SD 0.7, n=6 plots) vs control 4.1 (SD 0.6, n=6): lnRR = ln(4.8/4.1) = **0.1573** (+17%); variance = 0.7²/(6·4.8²) + 0.6²/(6·4.1²) = **0.00355+0.00357 = 0.0071**. If the paper analysed 60 plants as n, the variance would be understated about tenfold.""",
 examples=[("Crop","Yield under drought."),("Plant","Biomass under CO2."),("Seed","Germination."),("Soil","Fertiliser response."),("Pathology","Disease severity.")],
 mistakes=["Plants as n.","Mixing t/ha and g/plant.","lnRR with zero means.","Ignoring split-plot structure."],
 misconceptions=[("'Pots in a greenhouse are always independent.'","Bench position effects exist."),("'Field data are always more valid.'","Different questions.")],
 controversies=["lnRR bias corrections.","Pooling greenhouse and field."],
 decision_tree=[("Positive ratio data?","lnRR."),("Zeros/negatives?","MD/SMD."),("Split-plot?","Use the correct stratum n."),("Several harvests?","Dependence plan.")],
 exercises=["Compute lnRR and variance for your own numbers.","Define unit and design for three studies.","List moderators."],
 integrity="State unit conversions and design assumptions; do not inflate n.", further=["hedges1999","koricheva2014","nakagawa2012","nakagawa2023"],
 coding=dict(r='library(metafor)\nescalc(measure="ROM", m1i=4.8, sd1i=0.7, n1i=6, m2i=4.1, sd2i=0.6, n2i=6)', python='from metalab import stats as S\nprint(S.log_response_ratio(4.8, 0.7, 6, 4.1, 0.6, 6))'),
 application="**Milestone 7/9:** define units and the effect measure for plant outcomes.", checklist=["Unit = plot/pot","Units harmonised","lnRR validity checked","Moderators pre-specified"],
 quiz=[dict(q="lnRR for 4.8 vs 4.1?", opts=["0.157","0.7","1.17","0.5"], ans=0, why="ln(4.8/4.1).", numeric=True),
  dict(q="Unit of analysis in a pot experiment?", opts=["Pot","Plant","Leaf","Seed"], ans=0, why="Module 85."),
  dict(q="lnRR is invalid when...", opts=["Means can be zero or negative","Means are positive","n is large","SD is small"], ans=0, why="Log of ratio."),
  dict(q="Several harvests per study cause...", opts=["Dependence","Independence","Bias only","No issue"], ans=0, why="Repeated measures."),
  dict(q="Units must be harmonised...", opts=["Before computing lnRR","After pooling","Never","In the title"], ans=0, why="Common scale.")])

add(id=62, title="Microbiology and infectious-disease syntheses", last_verified=V, prerequisites=["Modules 27, 31, 85"],
 objectives=["Work on the log10 scale and handle detection limits.", "Distinguish biological from technical replicates.", "Plan for rare/zero counts and compositional data issues."],
 why="Microbial outcomes are logarithmic, censored at detection limits and often pseudoreplicated.",
 plain="""Common outcomes: **log10 CFU/mL reduction**, MIC, prevalence, abundance. Analyse on the log scale: a mean difference of log10 values is a ratio on the original scale. **Detection limits**: values 'ND' are *censored*, not zero. **Replicates**: independent cultures/experiments are biological replicates; wells/plates from one culture are technical.""",
 intermediate="""Log reduction = log10(N_control/N_treated): e.g. CFU 5×10^6 vs 1×10^4 → log10(500) = **2.70**. Substituting half the detection limit for non-detects is a common but biased convention - label it, report how many values were censored, and run sensitivity analyses. Count/prevalence outcomes with zeros need rare-event methods (Module 28/33/48). Microbiome relative-abundance data are **compositional** (Module 49, outline): do not treat proportions as independent.""",
 advanced="""Censored-data methods (Tobit/Kaplan-Meier on reversed scale, multiple imputation) are specialist. MIC values are interval-censored (doubling dilutions). Taxonomic revisions change names - include synonyms in searches.""",
 assumptions=["Log-normal-like counts.","Independent biological replicates."],
 worked_example="""Final CFU/mL: control 5.0×10^6, treated 1.0×10^4. Log reduction = log10(5.0×10^6) − log10(1.0×10^4) = 6.699 − 4.000 = **2.699**. If two of six treated replicates were non-detects (limit 10 CFU/mL) and were imputed at 5 CFU/mL, the mean log10 count shifts downward: label the study 'censoring present' and exclude/impute in sensitivity analyses.""",
 examples=[("Antimicrobial","Time-kill."),("Biofilm","CFU counts."),("Epidemiology","Prevalence."),("Microbiome","Compositional data."),("Resistance","MIC.")],
 mistakes=["Entering ND as zero.","Technical replicates as n.","Back-transforming means incorrectly.","Mixing log10 and ln."],
 misconceptions=[("'Zero CFU = zero bacteria.'","Below detection limit."),("'Log scale is cosmetic.'","It changes the estimand.")],
 controversies=["Handling non-detects.","Compositional analysis."],
 decision_tree=[("Counts?","Log10, MD of logs."),("Non-detects?","Label censoring; sensitivity."),("Proportions across taxa?","Compositional methods (specialist).")],
 exercises=["Compute log reductions from raw CFU.","Identify biological vs technical replicates in a paper.","Write a non-detect handling rule."],
 integrity="Do not hide censoring; label substitutions.", further=["sweeting2004","bradburn2007","mathes2017"],
 coding=dict(r='log10(5.0e6) - log10(1.0e4)   # 2.699', python='import math\nprint(math.log10(5.0e6) - math.log10(1.0e4))'),
 application="**Milestone 7:** record replicate type, detection limits and units.", checklist=["Replicates classified","Detection limits recorded","Scale stated"],
 quiz=[dict(q="log10(5×10^6) − log10(1×10^4)?", opts=["2.70","6.7","4.0","500"], ans=0, why="log10(500).", numeric=True),
  dict(q="'ND' should be entered as...", opts=["Censored/missing with a label","Zero","The mean","One"], ans=0, why="Below detection."),
  dict(q="Technical replicates are...", opts=["Not independent biological replicates","Independent","Better","Equal to cultures"], ans=0, why="Module 85."),
  dict(q="Mean difference of log10 values equals...", opts=["Log of the ratio of (geometric) means","Difference of means","Ratio of SDs","A hazard"], ans=0, why="Log properties."),
  dict(q="Relative abundances are...", opts=["Compositional","Independent","Normal","Counts"], ans=0, why="Sum to 1.")])

add(id=63, title="Ecology, evolution and environmental syntheses", last_verified=V, prerequisites=["Modules 27, 38"],
 objectives=["Choose lnRR/SMD/Zr and plan multilevel/phylogenetic structure.", "Handle many effect sizes per study and spatial/phylogenetic dependence.", "Use CEE/ROSES guidance for conduct and reporting."],
 why="Ecological datasets are hierarchical and heterogeneous; methods must acknowledge it.",
 plain="""Typical effect sizes: **lnRR**, SMD, **Fisher's z** for correlations. Studies often contribute several effects (species, sites, times). Heterogeneity is the norm. Guidance: Collaboration for Environmental Evidence handbook and **ROSES** reporting (Haddaway et al. 2018); methods overviews by Nakagawa and colleagues (Nakagawa & Santos 2012; Nakagawa et al. 2017 on appraising meta-analyses in biology; Nakagawa et al. 2023 practical guide) and Gurevitch et al. (2018).""",
 intermediate="""Use multilevel models (study/effect random effects), consider phylogenetic and spatial correlation, report heterogeneity as τ² *and* prediction intervals, and avoid vote counting. Publication bias tests must account for dependence. Moderators: taxon, biome, intervention intensity; prefer within-study contrasts. Data/code sharing is standard in the field.""",
 advanced="""Phylogenetic meta-analysis requires a tree (Open Tree of Life, candidate resource) and models in metafor/MCMCglmm; MetaLab does not implement them. Effect sizes for variability (lnVR, lnCVR) are used for variance questions.""",
 assumptions=["Dependence modelled.","Ratio-scale for lnRR."],
 worked_example="""Warming experiments, 4 studies, 7 effects: ignoring shared control plots within Study 2 would double-count the control. Plan: three-level model (study/effect) + sensitivity with one effect per study; report τ²_study, τ²_effect, I² (multilevel definition needs care) and a prediction interval.""",
 examples=[("Warming","Species richness."),("Invasives","Native abundance."),("Fertiliser","Biomass."),("Conservation","Intervention effectiveness."),("Evolution","Selection strength.")],
 mistakes=["Treating all effects as independent.","Ignoring publication bias under dependence.","Overusing meta-regression.","Poor data sharing."],
 misconceptions=[("'Ecological data are too heterogeneous to synthesise.'","Heterogeneity is estimated and explained, not hidden."),("'Vote counting is fine.'","Discouraged.")],
 controversies=["lnRR bias.","Phylogenetic corrections."],
 decision_tree=[("Many effects/study?","Multilevel."),("Cross-species?","Phylogeny."),("Ratio-scale?","lnRR.")],
 exercises=["Draft a multilevel model structure for your data.","List dependence sources.","Read ROSES items and map them."],
 integrity="Share data and code; report dependence handling.", further=["nakagawa2012","nakagawa2017meta","nakagawa2023","gurevitch2018","haddaway2018roses","koricheva2014"],
 application="**Milestone 4/10:** plan the random structure and sensitivity analyses.", checklist=["Dependence identified","Structure pre-specified","Prediction interval planned"],
 quiz=[dict(q="Ecological meta-analyses commonly use...", opts=["lnRR, SMD, Fisher's z with multilevel models","Only p-values","Only OR","Only vote counts"], ans=0, why="Field practice."),
  dict(q="Multiple effects per study require...", opts=["Modelling dependence","Ignoring it","Averaging always","Removing studies"], ans=0, why="Module 38."),
  dict(q="Which reporting standard fits environmental syntheses?", opts=["ROSES","MOOSE","ENTREQ","STROBE"], ans=0, why="Haddaway 2018."),
  dict(q="Vote counting is...", opts=["Discouraged","Recommended","Required","Quantitative"], ans=0, why="Ignores effect size/precision."),
  dict(q="MetaLab implements phylogenetic models?", opts=["No","Yes","Partly via CR2","Via GLMM"], ans=0, why="Stated limits.")])

add(id=65, title="Education and social-science syntheses", last_verified=V, prerequisites=["Modules 27, 85"],
 objectives=["Handle clustered designs (classrooms) via effect-size adjustments.", "Compare outcomes on different scales with SMD.", "Plan moderators and quasi-experimental appraisal."],
 why="Educational studies are clustered and use diverse measures; naive effect sizes mislead.",
 plain="""Outcomes (test scores, attitudes) differ by instrument → **SMD (Hedges' g)**. Interventions are often assigned to **classrooms/schools**: students are not independent. Hedges (2007) derived effect sizes and variances for cluster-randomised designs. Campbell Collaboration methods provide standards.""",
 intermediate="""With cluster assignment, adjust variances or n via the design effect (needs ICC; education often has ICC ≈ 0.1-0.25 - choose and test, don't hide). Pre-test/post-test and change scores need correlation assumptions. Implementation fidelity and baseline equivalence are key appraisal domains in quasi-experiments. Report outcome construct comparability and instrument reliability.""",
 advanced="""Three-level structure (students in classrooms in schools) leads to three-level effect-size formulas. Aggregated and individual-level analyses estimate different quantities.""",
 assumptions=["ICC assumed/known.","Comparable constructs."],
 worked_example="""100 students per group in classes of 25, ICC 0.10: DEFF = 1+(25−1)·0.10 = **3.4**, n_eff = 100/3.4 ≈ **29.4**. (The Virtual Lab education scenario uses a protocol design-effect rule with m=25, ICC 0.10 stated in its text.)""",
 examples=[("K-12","Reading outcomes."),("University","Exam scores."),("Teacher training","Attitudes."),("STEM","Engagement scales."),("Policy","School programmes.")],
 mistakes=["Ignoring clustering.","Mixing constructs.","Not stating ICC.","Ignoring baseline differences."],
 misconceptions=[("'Student n is the sample size.'","Classrooms are the units."),("'Different tests cannot be combined.'","SMD can, with construct caution.")],
 controversies=["ICC choice.","Standardising by pooled SD vs control SD."],
 decision_tree=[("Cluster-assigned?","Adjust for clustering."),("Different scales?","SMD."),("Baseline unbalanced?","Adjust/flag.")],
 exercises=["Compute DEFF and n_eff for your design.","Run the Virtual Lab education scenario.","Draft RoB domains for quasi-experiments."],
 integrity="State ICC assumptions and run sensitivity analyses.", further=["hedges2007cluster","lazic2018","borenstein2009book","hedges1981"],
 coding=dict(r='deff <- 1 + (25 - 1) * 0.10; c(deff, 100 / deff)   # 3.4 29.41', python='from metalab import advanced as A\nd = A.design_effect(25, 0.10); print(d, 100 / d)'),
 application="**Milestone 9:** apply the pre-specified clustering adjustment.", checklist=["Cluster structure identified","ICC stated","Sensitivity run"],
 quiz=[dict(q="DEFF for m=25, ICC 0.10?", opts=["3.4","2.5","25","0.1"], ans=0, why="1+24×0.1.", numeric=True),
  dict(q="Effective n for 100 students?", opts=["29.4","100","3.4","25"], ans=0, why="100/3.4.", numeric=True),
  dict(q="Different test scales are combined using...", opts=["SMD","MD","lnRR","OR"], ans=0, why="Standardised."),
  dict(q="Classroom-assigned interventions make students...", opts=["Non-independent","Independent","Equal","Random"], ans=0, why="Cluster."),
  dict(q="ICC assumptions should be...", opts=["Stated and tested","Hidden","Ignored","Always 0"], ans=0, why="Transparency.")])

add(id=1, title="Scientific reasoning: evidence, causation and uncertainty", last_verified=V, prerequisites=["None"],
 objectives=["Distinguish association, confounding and causation.", "Explain validity, reliability, replication and reproducibility.", "Appreciate why single studies and hierarchies of evidence are limited."],
 why="Evidence synthesis is applied scientific reasoning; its conclusions are only as sound as the reasoning behind each step.",
 plain="""Science proceeds by hypotheses, predictions and tests under uncertainty. **Association** is not **causation**: confounders can create or hide relationships; randomisation, controls and design address this. **Internal validity** (is the effect real in this study?) differs from **external validity** (does it generalise?). **Reliability** is consistency of measurement; **validity** is measuring what you intend. **Replication** repeats a study; **reproducibility** reruns an analysis on the same data. Ioannidis (2005) argued that many published findings may be false under common conditions such as small studies and flexible analyses - a reason for pre-specification, replication and synthesis (cited as further reading; read it critically).""",
 intermediate="""Causal criteria (e.g. Bradford Hill's considerations) are guides, not checklists. Statistical uncertainty (sampling error) differs from systematic error (bias). Hierarchies of evidence rank designs but are heuristics: a poor RCT can be worse than a good observational study; certainty frameworks (Module 52) weigh several factors.""",
 advanced="""Causal inference formalisms (potential outcomes, DAGs) clarify confounding; meta-analysis of observational studies pools estimates with shared biases. Multiple testing, selective reporting and researcher degrees of freedom inflate false positives; replication across independent labs provides robust evidence.""",
 assumptions=["Careful distinction between design, measurement and analysis."],
 worked_example="""Observation: flies in vials near the incubator door live shorter. Is the door causal? Alternative explanations: temperature gradient (confounder), crowding, batch. Design fix: randomise vial positions; analysis fix: include position as a covariate. The review's job: record whether each study randomised positions.""",
 examples=[("Medicine","Observational vs RCT."),("Ecology","Natural experiments."),("Education","Self-selection."),("Genetics","Genetic background."),("Plants","Bench effects.")],
 mistakes=["Inferring causation from correlation.","Equating significance with importance.","Ignoring confounders.","Over-trusting single studies."],
 misconceptions=[("'Replication = reproducibility.'","Different concepts."),("'The evidence pyramid is a law.'","It is a heuristic.")],
 controversies=["Evidence hierarchies.","Reproducibility crisis framing."],
 decision_tree=[("Randomised?","Stronger causal inference, still check conduct."),("Observational?","Confounding assessment."),("Single study?","Seek replication/synthesis.")],
 exercises=["List confounders for a claim in your field.","Explain internal vs external validity for a fly study.","Find one replication of a published finding."],
 integrity="Report limitations honestly; avoid causal language unsupported by design.", further=["ioannidis2005","higgins2011rob","guyatt2008"],
 application="**Milestone 1:** note the causal claim your review will address and the designs that can support it.", checklist=["Causal question stated","Confounders listed","Design limits acknowledged"],
 quiz=[dict(q="Reproducibility means...", opts=["Re-running an analysis to get the same results","Repeating the experiment","Peer review","Publishing"], ans=0, why="Distinct from replication."),
  dict(q="Association alone shows...", opts=["Not causation","Causation","Bias absence","Validity"], ans=0, why="Confounding."),
  dict(q="Internal validity concerns...", opts=["Whether the result is real in the study","Generalisability","Reliability only","Writing"], ans=0, why="Definition."),
  dict(q="Evidence hierarchies are...", opts=["Heuristics with limitations","Laws","Equal for all questions","Obsolete"], ans=0, why="Context matters."),
  dict(q="Pre-specification reduces...", opts=["Researcher degrees of freedom","Sample size","Reliability","Novelty"], ans=0, why="Analytic flexibility.")])

add(id=2, title="Study designs and what they can and cannot show", last_verified=V, prerequisites=["Module 1"],
 objectives=["Describe major designs and their typical biases.", "Match designs to review types and synthesis methods.", "Recognise designs specific to laboratory biology, ecology and education."],
 why="Eligibility criteria, appraisal tools and effect measures all depend on design.",
 plain="""Experimental: randomised trials (parallel, cluster, crossover, factorial), controlled laboratory/animal/plant/microbial experiments, field experiments. Observational: cohort, case-control, cross-sectional, case series. Other: before-after, interrupted time series, quasi-experiments, diagnostic accuracy, prognostic and prediction studies, qualitative, mixed-methods, economic evaluations, omics studies. Each answers different questions and carries typical biases.""",
 intermediate="""Matching: intervention questions → experiments (RCT/controlled lab); etiology → cohort/case-control (PECO); prevalence → cross-sectional; accuracy → DTA designs; experiences → qualitative. Synthesis follows design: pool compatible designs separately or with design as a moderator; do not mix adjusted observational and randomised estimates uncritically. Appraisal tools are design-specific (Module 22).""",
 advanced="""Laboratory designs hide structure (blocks, batches, vials): analyse and appraise with the true randomisation structure. Ecological natural experiments and BACI designs need dependence-aware models. Omics studies need multiplicity and batch considerations.""",
 assumptions=["Design is correctly classified from the report."],
 worked_example="""A fly study: 'Treated vs control vials, randomised incubator positions, blinded scoring' = controlled laboratory experiment (preclinical intervention) → SYRCLE-style appraisal; effect size lnRR; unit vial. A human cohort: PECO; ROBINS-E/I-type tools; adjusted OR/HR synthesis.""",
 examples=[("Clinical","RCT."),("Preclinical","Controlled experiment."),("Ecology","BACI."),("Education","Quasi-experiment."),("Epidemiology","Cohort.")],
 mistakes=["Misclassifying designs.","Mixing designs without moderators.","Using the wrong appraisal tool.","Ignoring clustering."],
 misconceptions=[("'RCT = no bias.'","Conduct and analysis matter."),("'Observational can never be useful.'","Often the only evidence.")],
 controversies=["Pooling randomised and observational evidence.","Design labels in ecology."],
 decision_tree=[("Assigned by investigators?","Experimental."),("Observed exposure?","Observational."),("Accuracy/prognosis?","Specific designs.")],
 exercises=["Classify five studies from your area.","Choose appraisal tools for each design.","Write eligibility criteria for designs."],
 integrity="Specify eligible designs in the protocol; justify mixing.", further=["higgins2011rob","sterne2016robinsi","sterne2019rob2","hooijmans2014"],
 application="**Milestone 2/4:** list eligible designs and justify.", checklist=["Designs listed","Tools matched","Mixing rules stated"],
 quiz=[dict(q="Etiological questions with unassigned exposures use...", opts=["PECO and observational designs","PICO and RCTs only","PCC","SPIDER"], ans=0, why="Exposure."),
  dict(q="Appraisal tools are...", opts=["Design-specific","Universal","Optional","Same for all"], ans=0, why="Module 22."),
  dict(q="Mixing randomised and adjusted observational estimates should be...", opts=["Done cautiously, with design moderators/justification","Routine","Forbidden","Ignored"], ans=0, why="Different biases."),
  dict(q="A controlled fly experiment is...", opts=["An experimental (controlled laboratory) design","A cohort","A case series","Qualitative"], ans=0, why="Design."),
  dict(q="Clustered designs require...", opts=["Cluster-aware analysis","Nothing","More flies","Fewer studies"], ans=0, why="Module 85.")])

add(id=8, title="Registration and open protocols", last_verified=V, prerequisites=["Module 7"],
 objectives=["Explain what registration does and does not do.", "Compare registration venues by checking official current rules.", "Handle retrospective registration and amendments transparently."],
 why="Registration time-stamps your plan and helps others find ongoing reviews.",
 plain="""Registration deposits key protocol details in a public registry **before** data extraction (prospective). It supports transparency and reduces duplication; it is **not peer review** and does not guarantee quality. Candidate venues include PROSPERO (health-related reviews), OSF Registries (any discipline) and others; their scope, eligibility and fees **change - read the official pages yourself** (MetaLab states none of them). Booth et al. (2012) describe PROSPERO's rationale; Pieper & Rombey (2022) discuss where to register.""",
 intermediate="""If you register after screening or extraction, say so (retrospective). Amendments: update the registry entry with dates and reasons. Protocol publication (e.g. PRISMA-P-based) is another route. MetaLab never registers anything: it helps you prepare the content (Protocol/SAP drafts).""",
 advanced="""Comparisons of registry entries with published reports (Pieper et al.) show discrepancies are common; careful amendment logging protects credibility. For non-health topics check whether a registry accepts your review type.""",
 assumptions=["You verify venue rules on the official site."],
 worked_example="""Preparation checklist: question (PICO/PECO), eligibility, outcomes, planned searches, analysis plan (SAP draft), timeline, contacts, funding/COI. Decide the venue after reading its current instructions; register before extracting data; log the registration ID and date in Decisions.""",
 examples=[("Health","PROSPERO-type."),("Any","OSF Registries."),("Preclinical","Animal-study registries (candidate resources)."),("Ecology","OSF/CEE protocols."),("All","Protocol article.")],
 mistakes=["Registering after extraction without saying so.","Not logging amendments.","Assuming registration = approval.","Quoting fees from memory."],
 misconceptions=[("'Registration is peer review.'","It is a time-stamp."),("'Registered means rigorous.'","Quality still matters.")],
 controversies=["Registry scope for non-health reviews.","Detail required."],
 decision_tree=[("Data extracted yet?","If yes: retrospective; say so."),("Health-related?","Check PROSPERO scope on the official site."),("Other?","OSF or domain registry.")],
 exercises=["Draft registration content from your protocol.","Read two registries' current rules and compare (record dates).","Plan how you will log amendments."],
 integrity="Never register automatically; verify rules; report retrospective registration honestly.", further=["booth2012","pieper2022","shamseer2015","moher2015"],
 application="**Milestone 4:** prepare registration content; you decide venue and timing.", checklist=["Content prepared","Venue rules read","Date logged","Amendment plan"],
 quiz=[dict(q="Registration is...", opts=["A time-stamped public plan, not peer review","Peer review","Approval","Funding"], ans=0, why="Definition."),
  dict(q="Registering after extraction should be...", opts=["Stated as retrospective","Hidden","Called prospective","Avoided"], ans=0, why="Honesty."),
  dict(q="Registry fees/eligibility should be taken from...", opts=["Official pages (dated)","Memory","MetaLab","Forums"], ans=0, why="They change."),
  dict(q="Does MetaLab register protocols?", opts=["No - never automatically","Yes","Sometimes","On demand"], ans=0, why="Rule."),
  dict(q="Amendments should be...", opts=["Logged with dates and reasons","Silent","Retroactive","Deleted"], ans=0, why="Transparency.")])

add(id=53, title="Synthesis without meta-analysis (SWiM)", last_verified=V, prerequisites=["Modules 3, 35"],
 objectives=["Decide when quantitative pooling is not appropriate.", "Apply structured synthesis methods and report them with SWiM.", "Avoid vote counting based on significance."],
 why="Many reviews cannot pool; transparent alternative synthesis is a legitimate, rigorous outcome.",
 plain="""When studies are too different (outcomes, effect measures, designs) or lack data, use **structured synthesis**: group studies by pre-specified criteria, tabulate effects, summarise direction and magnitude, and present visually (**effect-direction plots**, harvest plots). Report using **SWiM** (Campbell et al. 2020; nine items). Avoid **vote counting** by statistical significance - it ignores effect size and precision.""",
 intermediate="""Standardise metrics where possible (e.g. express results as % change), present ranges with study sizes, state the synthesis rule *a priori*, and assess certainty qualitatively. Heterogeneity and limitations must be explicit. Even without pooling, risk of bias must be considered.""",
 advanced="""Combining p-values, Albatross plots and effect-direction approaches have limits and assumptions; they cannot estimate a pooled effect. A mixed approach (pool where compatible, describe the rest) is common.""",
 assumptions=["Grouping rules were pre-specified."],
 worked_example="""Ten fly studies on 'dietary restriction' with incompatible regimens: group by regimen type (3 groups), tabulate lifespan % change per study with n (vials), summarise direction per group (e.g. 'increase in 6/7 studies; range +5 to +30%'), and present an effect-direction plot; report with SWiM items; avoid 'significant in 6 of 10 studies' as the conclusion.""",
 examples=[("Preclinical","Different regimens."),("Education","Different outcomes."),("Policy","Heterogeneous interventions."),("Public health","Diverse exposures."),("Ecology","Incomparable metrics.")],
 mistakes=["Vote counting by p<0.05.","Post-hoc grouping.","Omitting sample sizes.","No limitations."],
 misconceptions=[("'No pooling = no rigour.'","Structured synthesis can be rigorous."),("'Counting significant studies is a synthesis.'","It discards magnitude and precision.")],
 controversies=["Visual summary choices.","Mixed methods."],
 decision_tree=[("Comparable estimand + data?","Meta-analysis."),("Not?","SWiM."),("Some comparable?","Mixed.")],
 exercises=["Design grouping rules for your topic.","Draw an effect-direction table.","Complete SWiM items for a mock synthesis."],
 integrity="Pre-specify synthesis methods; report all studies, not only convenient ones.", further=["campbell2020","page2021","higgins2011rob"],
 application="**Milestone 4/10:** define a fallback SWiM plan.", checklist=["Grouping rules","Direction plot","SWiM items","Limitations"],
 quiz=[dict(q="Vote counting by significance is...", opts=["Discouraged","Recommended","Equivalent to MA","Required"], ans=0, why="Ignores magnitude/precision."),
  dict(q="SWiM is...", opts=["Reporting guideline for synthesis without meta-analysis","A model","A database","A tool"], ans=0, why="Campbell 2020."),
  dict(q="Grouping rules should be...", opts=["Pre-specified","Chosen after results","Hidden","Random"], ans=0, why="Avoid bias."),
  dict(q="Without pooling, risk of bias is...", opts=["Still considered","Irrelevant","Removed","Optional"], ans=0, why="Credibility."),
  dict(q="An effect-direction plot shows...", opts=["Direction of effect per study with study attributes","A pooled estimate","Funnel","Heterogeneity"], ans=0, why="Visual summary.")])

add(id=55, title="Scoping reviews and evidence maps", last_verified=V, prerequisites=["Module 3"],
 objectives=["Use PCC and the main scoping-review frameworks.", "Chart data and present evidence maps.", "Report with PRISMA-ScR and interpret gaps carefully."],
 why="Scoping reviews map the extent and nature of evidence; they are right when the aim is not to estimate an effect.",
 plain="""Scoping-review steps (Arksey & O'Malley 2005; advanced by Levac et al. 2010; JBI guidance by Peters et al. 2015): identify the question (PCC), identify and select studies, **chart** data, collate/summarise/report, optionally consult stakeholders. Reporting follows **PRISMA-ScR** (Tricco 2018). Distinguish from systematic reviews (Munn 2018). Outputs: tables, **evidence maps** (e.g. intervention × outcome grids) and gap descriptions.""",
 intermediate="""Charting forms record population, concept, context, design, outcomes and key findings. Critical appraisal is optional in scoping reviews; state your choice. Gaps are *absence in the sampled literature* and depend on search comprehensiveness - interpret cautiously. A scoping review can precede a systematic review to refine questions.""",
 advanced="""Large evidence maps benefit from controlled vocabularies and interactive visualisation; reproducible pipelines (code + logs) matter. Machine assistance can prioritise screening but not replace judgement.""",
 assumptions=["Broad question with defined PCC.","Transparent charting."],
 worked_example="""Question: 'What interventions on model-organism ageing have been studied (organism × intervention type × outcome)?' Build a grid; counts per cell from charted studies; empty cells are *candidate* gaps requiring verification by searching other databases.""",
 examples=[("Ageing biology","Interventions × organisms."),("Education","STEM approaches × levels."),("Ecology","Threats × taxa."),("Health","Services mapping."),("Biotech","Methods × targets.")],
 mistakes=["Using a scoping review to answer effectiveness.","No charting form.","Over-interpreting empty cells.","Ignoring reporting guideline."],
 misconceptions=[("'Scoping is an easy systematic review.'","Different aims; still rigorous."),("'Gap = unstudied.'","May be unsearched.")],
 controversies=["Appraisal in scoping reviews.","Stakeholder consultation."],
 decision_tree=[("Aim to map?","Scoping."),("Aim to estimate effect?","Systematic review."),("Gaps claimed?","Verify with extra searching.")],
 exercises=["Write a PCC question for a mapping review.","Design a charting form.","Sketch an evidence map."],
 integrity="Do not present maps as effectiveness evidence; document searches.", further=["arksey2005","levac2010","peters2015","tricco2018","munn2018"],
 application="**Milestone 1/4:** decide whether a scoping review fits better than a meta-analysis.", checklist=["PCC defined","Charting form","PRISMA-ScR","Gap claims verified"],
 quiz=[dict(q="PCC stands for...", opts=["Population, Concept, Context","Patient, Control, Comparison","Place, Cost, Care","None"], ans=0, why="JBI framework."),
  dict(q="Scoping reviews follow which reporting guideline?", opts=["PRISMA-ScR","MOOSE","ENTREQ","CONSORT"], ans=0, why="Tricco 2018."),
  dict(q="An empty cell in an evidence map indicates...", opts=["A candidate gap needing verification","Proof of no research","Bias","An error"], ans=0, why="Depends on searches."),
  dict(q="Critical appraisal in scoping reviews is...", opts=["Optional; state your choice","Mandatory always","Forbidden","Irrelevant"], ans=0, why="Method choice."),
  dict(q="Use a scoping review to...", opts=["Map evidence/concepts","Estimate a pooled effect","Replace trials","Guarantee novelty"], ans=0, why="Munn 2018.")])
